package com.northstarbank.console.service;import com.northstarbank.console.domain.*;import com.northstarbank.console.security.AuthorizationService;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;
@Service public class RequestService{private static final Map<String,Set<String>> EDGES=Map.of("open",Set.of("assigned"),"assigned",Set.of("in_progress"),"in_progress",Set.of("escalated","pending_customer","resolved"),"escalated",Set.of("in_progress"),"pending_customer",Set.of("in_progress"),"resolved",Set.of("closed","reopened"),"reopened",Set.of("in_progress"));private final ServiceRequestRepository repo;private final AuthorizationService auth;private final AuditService audit;private final java.util.concurrent.ConcurrentMap<Long,String> callbackCodes=new java.util.concurrent.ConcurrentHashMap<>();public RequestService(ServiceRequestRepository r,AuthorizationService a,AuditService l){repo=r;auth=a;audit=l;}public List<ServiceRequest> list(){var d=auth.require("REQUEST_MANAGE",null,false);return repo.findTop50ByOwningBranchInOrderByCreatedAtDesc(branches(d.scope()));}public ServiceRequest get(long id){var r=repo.findById(id).orElseThrow();auth.require("REQUEST_MANAGE",r.owningBranch,false);return r;}public ServiceRequest create(String customer,String branch,String type,String notes){auth.require("REQUEST_MANAGE",branch,false);var r=repo.save(new ServiceRequest(customer,type,auth.user().employeeId(),branch,notes));audit.record("REQUEST_CREATED","service_request",1,customer,"effective_scope",null,"open");return r;}@Transactional public void transition(long id,String to,String resolution){var r=get(id);if(!EDGES.getOrDefault(r.status,Set.of()).contains(to))throw new ResponseStatusException(HttpStatus.CONFLICT,"Transition not allowed");String from=r.status;r.status=to;if(to.equals("assigned"))r.assignedTo=auth.user().employeeId();if(to.equals("resolved"))r.resolution=resolution;audit.record("REQUEST_TRANSITION","service_request",1,r.customerId,"workflow",from,to);}private Collection<String> branches(String s){if(s.contains("BANK"))return java.util.stream.IntStream.rangeClosed(1,9).mapToObj(i->"B0"+i).toList();List<String>x=new ArrayList<>();for(String v:s.split(",")){if(v.startsWith("B"))x.add(v);else if(v.startsWith("R")){int start=(Integer.parseInt(v.substring(1))-1)*3+1;for(int i=start;i<start+3;i++)x.add("B0"+i);}}return x;}public String issueCallbackCode(long id){var r=get(id);String code=String.valueOf(new java.util.Random().nextInt(900000)+100000);callbackCodes.put(id,code);audit.record("CALLBACK_CODE_ISSUED","service_request",1,r.customerId,"workflow",null,"issued");return code;}public boolean confirmCallback(long id,String code){var r=get(id);String expected=callbackCodes.get(id);boolean ok=expected!=null&&expected.equals(code);if(ok){callbackCodes.remove(id);audit.record("CALLBACK_CONFIRMED","service_request",1,r.customerId,"workflow",null,"confirmed");}return ok;}}
